<template><div class="chart-shell"><div class="chart-tools"><span class="chart-title">{{ activeStation }} · 历史4小时 + 未来4小时</span><span class="acc">ACC {{ acc == null ? '—' : acc.toFixed(2) + '%' }}</span><button :class="{active: mode === 'power'}" @click="mode='power'">实际/预测</button><button :class="{active: mode === 'error'}" @click="mode='error'">误差</button></div><div ref="el" class="chart"></div><div v-if="!points.length" class="chart-empty">暂无真实曲线数据</div></div></template>
<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { usePlatformStore } from '../../stores/platform'
import { platformApi } from '../../api/platform'
import type { ForecastPoint } from '../../api/types'
const props = defineProps<{ stationId?: string }>()
const store = usePlatformStore(); const el = ref<HTMLElement | null>(null); const points = ref<ForecastPoint[]>([]); const acc = ref<number|null>(null); const mode = ref<'power'|'error'>('power'); const activeStation = ref(props.stationId || 'FD0001'); let chart: echarts.ECharts | null = null; let refreshTimer:number|undefined; let loading=false; let loadSequence=0
async function load(id: string, force=false){ if(loading&&!force)return; const sequence=++loadSequence; loading=true; activeStation.value=id; try{ const [window,metrics]=await Promise.all([platformApi.forecastWindow(id,16),platformApi.forecastMetrics(id,24)]); if(sequence!==loadSequence || (store.selectedStationId && store.selectedStationId!==id))return; points.value=window.points; acc.value=metrics.acc ?? null; await nextTick(); render() }catch{if(sequence===loadSequence&&!points.value.length){points.value=[];acc.value=null;render()}}finally{if(sequence===loadSequence)loading=false} }
function render(){ if(!chart)return; const labels=points.value.map(p=>new Date(p.observed_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})); const actual=points.value.map(p=>p.actual_power_mw); const predicted=points.value.map(p=>p.predicted_power_mw); const error=points.value.map(p=>p.actual_power_mw==null||p.predicted_power_mw==null?null:p.actual_power_mw-p.predicted_power_mw); const forecastStart=points.value.findIndex(p=>p.predicted_power_mw!=null); const axisSource=mode.value==='power'?[...actual,...predicted]:error; const axisValues=axisSource.filter((v):v is number=>v!=null&&Number.isFinite(v)); const dataMin=axisValues.length?Math.min(...axisValues):0; const dataMax=axisValues.length?Math.max(...axisValues):1; const dataSpan=Math.max(dataMax-dataMin,Math.max(dataMax*0.08,0.2)); const axisMin=mode.value==='power'?Math.max(0,dataMin-dataSpan*0.18):dataMin-dataSpan*0.18; const axisMax=dataMax+dataSpan*0.18; chart.setOption({backgroundColor:'transparent',tooltip:{trigger:'axis',valueFormatter:(v:any)=>v==null?'—':`${Number(v).toFixed(3)} MW`},legend:{show:mode.value==='power',top:0,textStyle:{color:'#9ab7c9',fontSize:10},data:['真实功率','未来4小时预测']},grid:{left:42,right:12,top:28,bottom:28},xAxis:{type:'category',data:labels,axisLabel:{color:'#708ca2',fontSize:9},axisLine:{lineStyle:{color:'#31576c'}}},yAxis:{type:'value',min:axisMin,max:axisMax,scale:true,axisLabel:{color:'#708ca2',fontSize:9,formatter:(v:number)=>Number(v).toFixed(1)},splitLine:{lineStyle:{color:'rgba(105,196,226,.12)'}}},dataZoom:[{type:'inside'},{type:'slider',height:12,bottom:2,borderColor:'transparent',textStyle:{color:'#708ca2'}}],series:mode.value==='power'?[{name:'真实功率',type:'line',smooth:true,showSymbol:false,data:actual,lineStyle:{color:'#39d9ff',width:2},areaStyle:{color:'rgba(57,217,255,.12)'}},{name:'未来4小时预测',type:'line',smooth:true,showSymbol:true,symbolSize:4,data:predicted,lineStyle:{color:'#ffb45b',width:2},markArea:forecastStart>=0?{silent:true,label:{show:false},itemStyle:{color:'rgba(255,180,91,.06)'},data:[[{xAxis:labels[forecastStart]},{xAxis:labels[labels.length-1]}]]}:undefined}]:[{name:'预测误差 MW',type:'line',smooth:true,showSymbol:false,data:error,lineStyle:{color:'#ff8b7c',width:2},areaStyle:{color:'rgba(255,139,124,.12)'}}]},true)}
onMounted(()=>{if(el.value){chart=echarts.init(el.value);load(activeStation.value,true);refreshTimer=window.setInterval(()=>load(activeStation.value),5000)}}); watch(()=>store.selectedStationId,id=>{if(id)load(id,true)}); watch(mode,render); onUnmounted(()=>{loadSequence++;if(refreshTimer)window.clearInterval(refreshTimer);chart?.dispose()})
</script>
<style scoped>.chart-shell{position:relative;height:210px}.chart-tools{height:24px;display:flex;align-items:center;gap:6px}.chart-title{margin-right:auto;color:#7896a8;font-size:10px}.acc{color:#3ee5b1;font:10px ui-monospace,monospace;margin-right:5px}.chart-tools button{border:1px solid rgba(70,188,230,.2);background:transparent;color:#7896a8;padding:3px 7px;font-size:10px;cursor:pointer}.chart-tools button.active{color:#39d9ff;border-color:#39d9ff}.chart{height:184px}.chart-empty{position:absolute;inset:30px 0 0;display:grid;place-items:center;color:#7893a7;font-size:11px;background:rgba(3,15,27,.35)}</style>
